package core;

import core.Application.*;
import java.sql.*;
import java.util.*;



public final class Views {
    private static String h(String s) { if (s == null) return ""; return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;").replace("'", "&#39;"); }
    public static String css() {
        try { return java.nio.file.Files.readString(java.nio.file.Path.of("web", "style.css")); }
        catch (java.io.IOException e) { throw new IllegalStateException("Cannot read web/style.css", e); }
    }
    public static String dashboard(Store DB, User u) throws SQLException {
        StringBuilder b=new StringBuilder("<section class='welcome'><p class='eyebrow'>YOUR WORKSPACE</p><h1>Welcome back, "+h(u.username)+".</h1><p>Pick up where you left off.</p></section>");
        if (u.role.equals("student")) {
            b.append(DB.openExamLink(u)).append("<div class='cards'><a class='card action' href='/exam/start'><span class='icon'>✦</span><h2>Start an exam</h2><p>Choose a subject and begin. Save answers as you go.</p></a><a class='card action' href='/reviews'><span class='icon'>↗</span><h2>Teacher reviews</h2><p>Share feedback after completing an exam.</p></a></div>");
            b.append(DB.studentAnalytics(u)).append("<section class='card'><h2>Recent exam results</h2>").append(DB.studentResults(u)).append("</section>");
        } else if (u.role.equals("teacher")) {
            b.append("<div class='cards'><a class='card action' href='/question/new'><span class='icon'>＋</span><h2>Create questions</h2><p>Build your question bank by subject.</p></a><a class='card action' href='/answers'><span class='icon'>✓</span><h2>Review written answers</h2><p>Read descriptive responses and award marks.</p></a><a class='card action' href='/exam-settings'><span class='icon'>◷</span><h2>Set exam timers</h2><p>Choose the time limit for each subject.</p></a></div><section class='card'><h2>Your question bank</h2><p class='muted'>Delete archives a question. Past answers and coding attempts remain in your history.</p>").append(DB.teacherQuestions(u)).append("</section>");
        } else if (u.role.equals("admin")) b.append("<section class='card'><h2>System overview</h2><p>Review platform activity and user counts.</p><a class='button' href='/admin'>Open admin overview</a></section>");
        return b.toString();
    }
    public static String startExam(Store DB)throws SQLException{
        StringBuilder subjects=new StringBuilder("<option value='All Subjects'>All Subjects — ").append(ExamTimer.DEFAULT_MINUTES).append(" minutes</option>");
        for(String subject:DB.subjects())subjects.append("<option value='").append(h(subject)).append("'>").append(h(subject)).append(" — ").append(DB.examDuration(subject)).append(" minutes</option>");
        return "<section class='card narrow'><p class='eyebrow'>STUDENT</p><h1>Start an exam</h1><p>Each exam attempt gets its own timer. Other students can take their exams at the same time.</p><form method='post' action='/exam/start'><label>Subject<select name='subject'>"+subjects+"</select></label><button class='button'>Begin exam</button></form></section>";
    }
    public static String examSettings(Store DB,User teacher)throws SQLException{
        Map<String,Integer> settings=DB.teacherExamDurations(teacher);
        StringBuilder body=new StringBuilder("<section class='welcome'><p class='eyebrow'>TEACHER WORKSPACE</p><h1>Exam timers</h1><p>Set a time limit for each subject. The limit is saved with each student attempt and continues while the exam is paused.</p></section><div class='stack'>");
        if(settings.isEmpty())body.append("<section class='card empty'>Add an active question first. Its subject will appear here.</section>");
        for(var entry:settings.entrySet())body.append("<form class='card inline-form' method='post' action='/exam-settings'><div><h2>").append(h(entry.getKey())).append("</h2><p class='muted'>Current duration: ").append(entry.getValue()).append(" minutes</p></div><input type='hidden' name='subject' value='").append(h(entry.getKey())).append("'><label>Minutes<input type='number' name='durationMinutes' min='5' max='240' required value='").append(entry.getValue()).append("'></label><button class='button small'>Save timer</button></form>");
        return body.append("</div><p class='muted'>The default for All Subjects is ").append(ExamTimer.DEFAULT_MINUTES).append(" minutes.</p>").toString();
    }
    public static String examPage(Store DB,User u,int id,String run)throws SQLException{return DB.renderExam(u,id,run);}
    public static String results(Store DB,User u,int id)throws SQLException{return DB.results(u,id);}
        public static String questionForm(String type){if(!Set.of("mcq","descriptive","coding").contains(type))return "<section class='card narrow'><p class='eyebrow'>TEACHER</p><h1>Add a question</h1><p>Choose a format to start.</p><div class='cards'><a class='card action' href='/question/new?type=mcq'><h2>Multiple choice</h2></a><a class='card action' href='/question/new?type=descriptive'><h2>Written response</h2></a><a class='card action' href='/question/new?type=coding'><h2>Java coding</h2><p>Students submit Java code checked against test cases.</p></a></div></section>";StringBuilder b=new StringBuilder("<section class='card narrow'><p class='eyebrow'>TEACHER · ").append(h(type.toUpperCase(Locale.ROOT))).append("</p><h1>Add ").append(type.equals("mcq")?"multiple-choice":type.equals("coding")?"Java coding":"written response").append(" question</h1><p><a href='/question/new'>← Change question type</a></p><form method='post'><input type='hidden' name='type' value='").append(type).append("'><label>Subject<input name='subject' required maxlength='100' placeholder='e.g. Computer Science'></label><label>Question<textarea name='question' required rows='4'></textarea></label>");if(type.equals("mcq"))b.append("<div class='two-col'><label>Option A<input name='a' required></label><label>Option B<input name='b' required></label><label>Option C<input name='c'></label><label>Option D<input name='d'></label></div><label>Correct option<select name='answer'><option>A</option><option>B</option><option>C</option><option>D</option></select></label>");if(type.equals("coding")){b.append("<p class='muted'>Language: Java only. Use a public class named <code>Main</code> and read input from standard input.</p>");for(int i=1;i<=5;i++)b.append("<article class='card test-case'><h2>Test case ").append(i).append("</h2><label>Input<textarea name='input").append(i).append("' rows='2' ").append(i==1?"required":"").append(" placeholder='Input sent to your program'></textarea></label><label>Expected output<textarea name='expected").append(i).append("' rows='2' ").append(i==1?"required":"").append(" placeholder='Expected standard output'></textarea></label><label class='check'><input type='checkbox' name='hidden").append(i).append("' value='1'> Hide this test case from students</label></article>");}return b.append("<button class='button'>Save question</button></form></section>").toString();}
    public static String answers(Store DB,User u)throws SQLException{return DB.renderAnswers(u);}
    public static String reviews(Store DB,User u)throws SQLException{return DB.renderReviews(u);}
    public static String admin(Store DB,User u)throws SQLException{return DB.renderAdmin(u);}

    public static String shell(User u,String title,String body){return "<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>"+h(title)+" · Evalio</title><link rel='stylesheet' href='/assets/style.css'><script src='/assets/exam.js' defer></script></head><body><header class='topbar'><a class='brand' href='/'><span class='brand-mark'>e</span> evalio<span class='brand-dot'>.</span></a><nav><a href='/'>Dashboard</a>"+(u.role.equals("student")?"<a href='/exam/start'>Exams</a><a href='/reviews'>Reviews</a>":u.role.equals("teacher")?"<a href='/question/new'>Questions</a><a href='/answers'>Responses</a><a href='/exam-settings'>Exam timers</a>":"<a href='/admin'>Admin</a><a href='/monitor'>OS / DBMS</a>")+"</nav><div class='account'><span class='avatar'>"+h(u.username.substring(0,1).toUpperCase())+"</span><span>"+h(u.username)+" <small>"+h(u.role)+"</small></span><a class='logout' href='/logout'>Log out</a></div></header><main class='main'>"+body+"</main><footer>Evalio <span>·</span> Exam workspace</footer></body></html>";}
    public static String login(String error){return authPage("Sign in","Welcome back","Sign in to continue to your workspace.","/login",false,error);}
    public static String register(String error){return authPage("Create your account","A better way to learn.","Join Evalio as a student or teacher.","/register",true,error);}
    public static String authPage(String title,String headline,String sub,String action,boolean registration,String error){return "<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>"+title+" · Evalio</title><link rel='stylesheet' href='/assets/style.css'></head><body class='auth-bg'><main class='auth-layout'><section class='auth-art'><a class='brand light' href='/login'><span class='brand-mark'>e</span> evalio<span class='brand-dot'>.</span></a><div class='art-copy'><p class='eyebrow'>EXAMS, MADE CLEAR</p><h1>Focus on what<br>you know.</h1><p>A calmer space to teach, learn, and see progress.</p></div><div class='art-foot'>Built for curious minds.</div></section><section class='auth-panel'><div class='auth-card'><p class='eyebrow'>"+(registration?"GET STARTED":"YOUR CLASSROOM")+"</p><h2>"+headline+"</h2><p class='muted'>"+sub+"</p>"+(error.isBlank()?"":alert(error))+"<form method='post' action='"+action+"'><label>Username<input name='username' required autocomplete='username' minlength='3' maxlength='60'></label><label>Password<input type='password' name='password' required autocomplete='"+(registration?"new-password":"current-password")+"' minlength='8'></label>"+(registration?"<label>I am a<select name='role'><option value='student'>Student</option><option value='teacher'>Teacher</option></select></label>":"")+"<button class='button wide'>"+(registration?"Create account":"Sign in")+" <span>→</span></button></form><p class='switch'>"+(registration?"Already have an account? <a href='/login'>Sign in</a>":"New to Evalio? <a href='/register'>Create an account</a>")+"</p></div></section></main></body></html>";}
    public static String alert(String m){return "<div class='alert'>"+h(m)+"</div>";}
    public static String options(List<String> values){StringBuilder b=new StringBuilder();for(String v:values)b.append("<option>").append(h(v)).append("</option>");return b.toString();}

}
